scwin.gComNm = frame.opener.key_com_nm;
scwin.gPublDdtm = frame.opener.key_publ_ddtm;
scwin.gFsAcntTpCd = frame.opener.key_fs_acnt_tp_cd;
scwin.gFsAcntTpNm = frame.opener.key_fs_acnt_tp_nm;
scwin.gDisclsTitle = frame.opener.key_discls_title;
scwin.gSubmitSysTp = ''; // 제출구문 - 한글자동변환 :0=국문제출, 1=영문제출
scwin.gProcs_063 = ''; // 시장조치관련 - 영문자동변환대상 : count(*)

scwin.gUrl = '';
scwin.gInterval;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_Init = function() {
    $c.stf.setObjectValue(txb_DISCLS_TITLE, scwin.gDisclsTitle);
    $c.stf.setObjectValue(txb_COM_NM, scwin.gComNm);
    $c.stf.setObjectValue(txb_FS_ACNT_TP_NM, scwin.gFsAcntTpNm);
    $c.stf.setObjectValue(txb_PUBL_DDTM, scwin.gPublDdtm);
    $c.stf.setObjectValue(txb_ACPT_NO, scwin.gAcptNo);

    //수정/삭제 버튼 활성화
    if (js_market == "1" || js_market == "2" || js_market == "6" || js_usr_tp_cd == "1") {
        $c.stf.showObj(panel_3, true);
    } else {
        $c.stf.showObj(panel_3, false);
    }

    //탭 비활성화
    MaxTab_01.setDisabled(true);
};
scwin.fn_setSaveHeader = function() {
    dts_delete.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=DSCLSTAT_IFRS_WRTRPT_EXTRC_INFO";
    dts_delete.Reset();
    dts_delete.insertRow();
};
scwin.fn_list_cd_sync = function() {
    var limit = 3;
    for (var i = 1; i <= limit; i++) {
        eval("fn_Search_n(" + i + ")"); //1_재무상태표, 2_손익계산서, 3_자본변동표

        if (i < limit) eval("fn_Search_Xbrl_n(" + i + ")"); //자본변동표는 수정불가

    }
};
scwin.fn_checkNum = function(row, colid, data, text) {
    var num = eval("dts_" + text).getCellData(row, colid);
    // ex) (1,632,712,242) 일시 음수로 본다.
    if (num.indexOf('(') > -1) {
        num = '-' + num;
    }
    num = num.replace(/\,|\(|\)/g, '');
    num = num.replace(/\s/g, '');
    eval("dts_" + text, num).setCellData(row, colid);
    if (isNaN(eval("dts_" + text).getCellData(row, colid))) {
        $c.win.alert("올바른 숫자형식으로 값을 입력해주세요.");
        //eval("dts_" + text).NameValue(row,colid) = "123";
        eval("grd_" + text).Focus();
    }
};
scwin.isDate = function(dd) {
    try {
        var y, m, d = "";
        if (dd.length != 8) {
            return false;
        } else {
            y = dd.substr(0, 4);
            m = dd.substr(4, 2);
            d = dd.substr(6, 2);
        }
        var date = new Date(y, m - 1, d);
        if (y == date.getFullYear() && m - 1 == date.getMonth() && d == date.getDate()) {
            return date;
        } else {
            return false;
        }
    } catch (e) {
        return false;
    }
};
scwin.fn_validCheck = function() {
    //숫자 확인_재무상태표
    for (var i = 1; i <= dts_1_1.getTotalRow(); i++) {
        dts_1_1.setRowPosition(i, 0);
        for (var a = 1; a < 3; a++) {
            var num = dts_1_1.getCellData(i, "text_1_" + a);
            if (!$c.ut.isNum(num < 0 ? num * (-1) : num)) {
                MaxTab_01.setSelectedTabIndex("1"); //탭이동
                $c.win.alert("숫자를 입력해 주세요.");
                grd_1_1.SetColumn("text_1_" + a);
                grd_1_1.focus();
                return false;
            }
        }
    }
    //숫자 확인_손익계산서
    for (var i = 1; i <= dts_2_1.getTotalRow(); i++) {
        dts_2_1.setRowPosition(i, 0);
        for (var a = 1; a < 5; a++) {
            var num = dts_2_1.getCellData(i, "text_2_" + a);
            if (!$c.ut.isNum(num < 0 ? num * (-1) : num)) {
                MaxTab_01.setSelectedTabIndex("2"); //탭이동
                $c.win.alert("숫자를 입력해 주세요.");
                grd_2_1.SetColumn("text_2_" + a);
                grd_2_1.focus();
                return false;
            }
        }
    }

    //입력여부 확인_재무상태표
    for (var i = 1; i <= dts_1_1.getTotalRow(); i++) {
        dts_1_1.setRowPosition(i, 0);
        for (var a = 0; a < 3; a++) {
            if (dts_1_1.getCellData(i, "text_1_" + a) == "") {
                MaxTab_01.setSelectedTabIndex("1"); //탭이동
                $c.win.alert("입력되지 않은 항목이 있습니다.");
                grd_1_1.SetColumn("text_1_" + a);
                grd_1_1.focus();
                return true;
            }
        }
    }
    //입력여부 확인_손익계산서
    for (var i = 1; i <= dts_2_1.getTotalRow(); i++) {
        dts_2_1.setRowPosition(i, 0);
        for (var a = 0; a < 5; a++) {
            if (dts_2_1.getCellData(i, "text_2_" + a) == "") {
                MaxTab_01.setSelectedTabIndex("2"); //탭이동
                $c.win.alert("입력되지 않은 항목이 있습니다.");
                grd_2_1.SetColumn("text_2_" + a);
                grd_2_1.focus();
                return true;
            }
        }
    }
    return true;
};
scwin.fn_Save = function() {
    //등록
    if (!scwin.fn_validCheck()) {
        return;
    }
    if (confirm('저장 하시겠습니까?')) {
        trs_Save.Action = "/IfrsDisclosureStatistics.do?method=saveIfrsWrtrptInfo&EMP_NO=" + js_emp_no + "&ACPT_NO=" + scwin.gAcptNo + "&FS_ACNT_TP_CD=" + scwin.gFsAcntTpCd + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_Save.KeyValue = "JSP(I:pInput1=dts_1_1,I:pInput2=dts_2_1)";
        trs_Save.Post();
    }
};
scwin.fn_Delete = function() {
    var str = scwin.gComNm + "의 [" + scwin.gFsAcntTpNm + "]보고서 추출데이터(" + scwin.gPublDdtm + ")를 [삭제]하시겠습니까?";
    if (confirm(str)) {

        //dts_delete.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
        dts_delete.insertRow();
        dts_delete.setCellData(1, "EMP_NO", js_emp_no);
        trs_Delete.Action = "/IfrsDisclosureStatistics.do?method=deleteIfrsWrtrptInfo&ACPT_NO=" + scwin.gAcptNo + "&FS_ACNT_TP_CD=" + scwin.gFsAcntTpCd + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
        trs_Delete.KeyValue = "JSP(I:pInput1=dts_delete)";
        trs_Delete.post();
    }
};
scwin.setHeadTitle = function(pos, a, b) {
    if (pos < 3) {
        eval("grd_2_" + pos, a).setColumnProp('groupName_2_' + pos + '_1', 'name');
        eval("grd_2_" + pos, b).setColumnProp('groupName_2_' + pos + '_2', 'name');
    } else {
        eval("grd_" + pos + "_1", a).setColumnProp('groupName_' + pos + '_1_1', 'name');
        eval("grd_" + pos + "_1", b).setColumnProp('groupName_' + pos + '_1_2', 'name');
