// 프레임셋 가운데 : 공시본문 셋팅
scwin.fn_getBodyContent = function(pUrl, pTocUrl) {
    var url = "/dsclproc/JLDSTF10005.jsp?" + "&body_url=" + pUrl + "&acpt_no=" + scwin.gAcptNo + "&gAskScrenID=" + "&gAccssAuthTpCd=01";
