scwin.grd_1_2_OnDblClick = function(row, colid) {
    if (colid == 'text_1_3') {
        var line = dts_1_2.getCellData(row, "LINE");
        dts_1_1.setRowPosition(line, 0);
        var col_0 = dts_1_2.getCellData(row, "text_1_0");
        var col_1 = dts_1_2.getCellData(row, "text_1_1");
        var col_2 = dts_1_2.getCellData(row, "text_1_2");
        var msg = col_0 + " : " + col_1 + ", " + col_2 + "\n\n적용하시겠습니까?";

        //grd_1_1의 같은 자리에 데이터 복사
        if (confirm(msg)) {
            dts_1_1.setCellData(line, "text_1_1", col_1);
            dts_1_1.setCellData(line, "text_1_2", col_2);
        }
    }
};
