scwin.dts_AcptProcs_OnLoadCompleted = function(rowcount) {
    var vDocNo = dts_AcptProcs.getCellData(1, "DISCLS_DOC_NO");
    var sMainFormCd = dts_AcptProcs.getCellData(1, "FORM_CD");
    var sFormVer = dts_AcptProcs.getCellData(1, "FORM_VER");
    var sLangTpCd = dts_AcptProcs.getCellData(1, "LANG_TP_CD");
    scwin.gSubmitSysTp = dts_AcptProcs.getCellData(1, "SUBMIT_SYS_TP_CD"); // 제출구문 - 한글자동변환 :0=국문제출, 1=영문제출	
    scwin.gProcs_063 = dts_AcptProcs.getCellData(1, "FPROCS_063"); // 시장조치관련 - 영문자동변환대상 : count(*)

    if (scwin.gSubmitSysTp == '0' && sLangTpCd == '1') {
        // 국문제출에서 제출한 영문공시를 디폴트로 볼때..
        scwin.fn_getDocHtmlURL(vDocNo, sMainFormCd, sFormVer, '0', scwin.gSubmitSysTp);
    } else {
        scwin.fn_getDocHtmlURL(vDocNo, sMainFormCd, sFormVer, sLangTpCd, scwin.gSubmitSysTp);
    }
};
scwin.dts_DocUrl_OnLoadCompleted = function(rowcount) {
    scwin.fn_getBodyContent(dts_DocUrl.getCellData(1, "BODY_URL"), dts_DocUrl.getCellData(1, "TOC_URL"));
};
scwin.btn_Modify_onclick = function() {
    scwin.fn_Save();
};
scwin.btn_Delete_onclick = function() {
    scwin.fn_Delete();
};
scwin.btn_Close_onclick = async function() {
    frame.opener.gRow = 0; //행 초기화
    await $c.frame.CloseFrame();
};
scwin.MaxTab_01_OnSelChanged = function(nIndex) {
    scwin.fn_MovePosition(nIndex);
};
scwin.gform_onload = function() {
    frame.width = 1926;
    frame.height = 840;
    scwin.fn_Init();
    scwin.fn_setSaveHeader();
    fn_HeadRead();
    scwin.gInterval = setInterval(fn_SetPosition, 100); //iframe callback이 안먹혀서 로딩이 끝났는지 인터벌로 확인

    scwin.fn_list_cd_sync();
};
